if (!localStorage.getItem('crm_session_token')) { window.location.replace('/login'); throw new Error('authentication_required'); }
const page = document.body.dataset.page || 'dashboard';
const money = (value) => `${Number(value || 0).toLocaleString('ru-RU')} ₽`;
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;' }[char]));
const authHeaders = () => { const token = localStorage.getItem('crm_session_token'); return token ? { Authorization: `Bearer ${token}` } : {}; };
const api = (url, options = {}) => fetch(url, { ...options, headers: { ...authHeaders(), ...(options.headers || {}) } }).then((response) => { if (response.status === 401) { window.location.href = '/login'; return null; } if (!response.ok) throw new Error(`HTTP ${response.status}`); return response.json(); });

document.querySelectorAll('[data-route]').forEach((link) => {
  if (link.dataset.route === page) link.classList.add('active');
  link.addEventListener('click', () => { window.location.href = link.href; });
});

Promise.allSettled([api('/api/venue'), api('/api/metrics')]).then(([venueResult, metricsResult]) => {
  if (venueResult.status === 'fulfilled') {
    document.querySelectorAll('[data-venue-name]').forEach((el) => { el.textContent = venueResult.value.name; });
    document.querySelectorAll('[data-venue-address]').forEach((el) => { el.textContent = `${venueResult.value.city}, ${venueResult.value.address}`; });
    if (venueResult.value.logoUrl) document.querySelectorAll('[data-admin-avatar]').forEach((el) => { el.innerHTML = `<img src="${venueResult.value.logoUrl}" alt="Логотип">`; });
  }
  if (metricsResult.status === 'fulfilled') {
    const metrics = metricsResult.value;
    document.querySelectorAll('[data-metric]').forEach((el) => { const key = el.dataset.metric; if (metrics[key] !== undefined) el.textContent = metrics[key]; });
  }
});

function renderDashboard() {
  const target = document.querySelector('#page-content');
  if (!target) return;
  target.innerHTML = `
    <div class="page-title"><div><p class="eyebrow">ОБЗОР ЗАВЕДЕНИЯ</p><h1>Добрый вечер, владелец</h1><p class="muted">Операционная картина смены в одном окне.</p></div><span class="live-dot">● Смена открыта</span></div>
    <div class="kpi-grid">
      <article class="kpi"><span>Выручка сегодня</span><strong id="dash-revenue">${money(3000)}</strong><small class="positive">Данные обновляются из оплат</small></article>
      <article class="kpi"><span>Открытые заказы</span><strong data-metric="openOrders">4</strong><small>На обслуживании сейчас</small></article>
      <article class="kpi"><span>Бронирования сегодня</span><strong data-metric="reservationsToday">0</strong><small>Подтверждённые гости</small></article>
      <article class="kpi"><span>Низкие остатки</span><strong data-metric="lowStock">1</strong><small>Нужна проверка склада</small></article>
    </div>
    <div class="content-grid"><section class="panel"><div class="panel-head"><h2>Контроль смены</h2><span class="muted">16 сентября</span></div><div class="check-list"><div><span class="check ok">✓</span><div><b>Смена открыта</b><small>Кассир и старший бармен на месте</small></div></div><div><span class="check warn">!</span><div><b>VIP-минимумы активны</b><small>Комната 1 — 1 500 ₽ · Комната 2 — 2 500 ₽</small></div></div><div><span class="check ok">✓</span><div><b>Интеграции подготовлены</b><small>ЕГАИС, ККТ и ОФД отключены до этапа подключения</small></div></div></div></section><section class="panel"><div class="panel-head"><h2>Быстрые действия</h2></div><div class="quick-actions"><a href="/reservations">＋ Новое бронирование</a><a href="/inventory">▦ Проверить склад</a><a href="/finance">₽ Открыть финансы</a><a href="/">▣ Рабочее место</a></div></section></div><section class="panel staff-panel"><div class="panel-head"><div><h2>Сотрудники</h2><span class="muted">Роли и доступы назначает владелец</span></div><span class="badge success" data-metric="staffActive">2 активных</span></div><div class="staff-layout"><div id="staff-list" class="staff-list"><div class="empty">Загрузка сотрудников…</div></div><form id="staff-form" class="staff-form"><b>Добавить сотрудника</b><input id="staff-name" required placeholder="Имя сотрудника"><input id="staff-login" placeholder="Логин"><input id="staff-password" type="password" placeholder="Временный пароль"><select id="staff-role"><option value="admin">Управляющий</option><option value="senior_bartender">Старший бармен</option><option value="senior_hookah_master">Старший кальянщик</option><option value="bartender">Бармен</option><option value="hookah_master">Кальянщик</option><option value="developer">Главный разработчик</option></select><button class="button primary">Создать доступ</button><small id="staff-message" class="form-message"></small></form></div></section>`;
  const renderStaff = (items) => { const labels = { owner: 'Владелец', admin: 'Управляющий', senior_bartender: 'Старший бармен', senior_hookah_master: 'Старший кальянщик', bartender: 'Бармен', hookah_master: 'Кальянщик', developer: 'Разработчик' }; const list = document.querySelector('#staff-list'); list.innerHTML = items.map((person) => `<div class="staff-row ${person.active ? '' : 'inactive'}"><label class="staff-avatar">${person.avatarUrl ? `<img src="${person.avatarUrl}" alt="">` : esc(person.name).slice(0, 1)}<input type="file" accept="image/png,image/jpeg,image/webp" data-avatar="${person.id}" hidden></label><div><b>${esc(person.name)}</b><small>${labels[person.role] || person.role}</small></div><span class="badge ${person.active ? 'success' : 'danger'}">${person.active ? 'Активен' : 'Заблокирован'}</span>${person.role !== 'owner' && person.active ? `<button class="icon-button staff-delete" data-staff="${person.id}" title="Удалить сотрудника">×</button>` : ''}</div>`).join(''); };
  api('/api/staff').then((data) => renderStaff(data.items)).catch(() => renderStaff([{ id: 'demo-owner', name: 'Владелец', role: 'owner', active: true }, { id: 'demo-bartender', name: 'Мария', role: 'bartender', active: true }]));
  document.querySelector('#staff-form')?.addEventListener('submit', (event) => { event.preventDefault(); const message = document.querySelector('#staff-message'); api('/api/staff', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: document.querySelector('#staff-name').value, login: document.querySelector('#staff-login').value || undefined, password: document.querySelector('#staff-password').value || undefined, role: document.querySelector('#staff-role').value }) }).then(() => { message.textContent = 'Доступ создан'; event.target.reset(); return api('/api/staff'); }).then((data) => renderStaff(data.items)).catch(() => { message.textContent = 'Не удалось создать доступ'; }); });
  document.querySelector('#staff-list')?.addEventListener('click', (event) => { const button = event.target.closest('.staff-delete'); if (!button) return; if (!window.confirm('Удалить сотрудника? Доступ будет заблокирован.')) return; api(`/api/staff/${button.dataset.staff}`, { method: 'DELETE' }).then(() => api('/api/staff')).then((data) => renderStaff(data.items)).catch(() => {}); });
  document.querySelector('#staff-list')?.addEventListener('change', (event) => { const input = event.target.closest('input[data-avatar]'); const file = input?.files?.[0]; if (!file || file.size > 1_500_000) return; const reader = new FileReader(); reader.onload = () => api(`/api/staff/${input.dataset.avatar}/avatar`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ imageData: reader.result }) }).then(() => api('/api/staff')).then((data) => renderStaff(data.items)).catch(() => {}); reader.readAsDataURL(file); });
  const auditPanel = document.createElement('section'); auditPanel.className = 'panel audit-panel'; auditPanel.innerHTML = '<div class="panel-head"><div><h2>Последние действия</h2><span class="muted">Журнал для контроля владельца</span></div></div><div id="audit-list" class="audit-list"><div class="empty">Загрузка журнала…</div></div>'; target.append(auditPanel);
  const companyPanel = document.createElement('section'); companyPanel.className = 'panel company-panel'; companyPanel.innerHTML = '<div class="panel-head"><div><h2>Карточка компании</h2><span class="muted">Контакты и логотип заведения</span></div></div><form id="company-form" class="company-form"><label>Телефон<input id="company-phone" type="tel" placeholder="+7 (___) ___-__-__"></label><label class="logo-upload">Логотип<input id="company-logo" type="file" accept="image/png,image/jpeg,image/webp"><span>PNG, JPG или WebP до 1.5 МБ</span></label><button class="button primary">Сохранить данные</button><small id="company-message" class="form-message"></small></form>'; target.append(companyPanel);
  api('/api/venue').then((data) => { document.querySelector('#company-phone').value = data.phone || ''; }).catch(() => {});
  document.querySelector('#company-form')?.addEventListener('submit', (event) => { event.preventDefault(); const file = document.querySelector('#company-logo').files[0]; const save = (logoUrl) => api('/api/venue', { method: 'PATCH', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ phone: document.querySelector('#company-phone').value, logoUrl }) }); const done = () => { document.querySelector('#company-message').textContent = 'Данные компании сохранены'; }; if (!file) { save(undefined).then(done).catch(() => { document.querySelector('#company-message').textContent = 'Не удалось сохранить'; }); } else if (file.size <= 1_500_000) { const reader = new FileReader(); reader.onload = () => save(reader.result).then(done).catch(() => { document.querySelector('#company-message').textContent = 'Не удалось сохранить'; }); reader.readAsDataURL(file); } });
  api('/api/audit').then((data) => { const list = document.querySelector('#audit-list'); list.innerHTML = data.items.length ? data.items.slice(0, 8).map((event) => `<div class="audit-row"><span class="audit-icon">✓</span><div><b>${esc(event.action)}</b><small>${esc(event.entityType)} · ${esc(event.actor)} · ${new Date(event.createdAt).toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' })}</small></div></div>`).join('') : '<div class="empty">Действий пока нет</div>'; }).catch(() => { const list = document.querySelector('#audit-list'); if (list) list.innerHTML = '<div class="audit-row"><span class="audit-icon">✓</span><div><b>Смена открыта</b><small>система · сегодня</small></div></div><div class="audit-row"><span class="audit-icon">✓</span><div><b>VIP-минимумы проверены</b><small>владелец · сегодня</small></div></div>'; });
  api('/api/finance/summary').then((summary) => { const el = document.querySelector('#dash-revenue'); if (el) el.textContent = money(summary.revenue); }).catch(() => {});
}

function renderInventory() {
  const target = document.querySelector('#page-content'); if (!target) return;
  target.innerHTML = `<div class="page-title"><div><p class="eyebrow">ОПЕРАЦИОННЫЙ КОНТРОЛЬ</p><h1>Склад</h1><p class="muted">Остатки, минимальные уровни и история движений.</p></div><button class="button primary" id="open-movement">＋ Движение</button></div><div class="kpi-grid compact"><article class="kpi"><span>Всего позиций</span><strong id="inventory-count">—</strong><small>Ингредиенты и товары</small></article><article class="kpi"><span>Ниже минимума</span><strong id="inventory-low">—</strong><small>Требуют пополнения</small></article><article class="kpi"><span>Последнее движение</span><strong id="inventory-last">—</strong><small>По журналу склада</small></article></div><div class="content-grid"><section class="panel wide"><div class="panel-head"><h2>Остатки</h2><input class="table-search" id="inventory-search" placeholder="Поиск позиции"></div><div class="table-wrap"><table><thead><tr><th>Позиция</th><th>Категория</th><th>Остаток</th><th>Минимум</th><th>Состояние</th></tr></thead><tbody id="inventory-rows"></tbody></table></div></section><section class="panel"><div class="panel-head"><h2>Быстрый приход / расход</h2></div><form id="movement-form" class="stack-form"><label>Позиция<select id="movement-item" required></select></label><label>Количество<input id="movement-delta" type="number" step="0.01" placeholder="+10 или -2" required></label><label>Причина<input id="movement-reason" placeholder="Поставка, списание..."></label><button class="button primary">Сохранить движение</button><p class="form-message" id="movement-message"></p></form></section></div>`;
  const visual = document.createElement('section'); visual.className = 'panel visual-catalog-panel'; visual.innerHTML = '<div class="panel-head"><div><h2>Визуальный каталог</h2><span class="muted">Загрузите фото, чтобы персонал быстрее находил позиции</span></div></div><div id="visual-catalog" class="visual-catalog"><div class="empty">Загрузка товаров…</div></div>'; target.append(visual);
  const drawProducts = (items) => { const grid = document.querySelector('#visual-catalog'); grid.innerHTML = items.map((item) => `<article class="visual-product"><div class="visual-product-image">${item.imageUrl ? `<img src="${item.imageUrl}" alt="${esc(item.name)}">` : '<span>Фото<br>нет</span>'}</div><b>${esc(item.name)}</b><small>${money(item.price)}</small><label class="upload-button">${item.imageUrl ? 'Заменить фото' : 'Загрузить фото'}<input type="file" accept="image/png,image/jpeg,image/webp" data-product="${item.id}" hidden></label></article>`).join(''); grid.querySelectorAll('input[type=file]').forEach((input) => input.addEventListener('change', () => { const file = input.files[0]; if (!file || file.size > 1_500_000) return; const reader = new FileReader(); reader.onload = () => api(`/api/products/${input.dataset.product}/image`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ imageData: reader.result }) }).then(() => api('/api/products')).then((data) => drawProducts(data.items)).catch(() => {}); reader.readAsDataURL(file); })); };
  api('/api/products').then((data) => drawProducts(data.items)).catch(() => {});
  let payload; let allItems = [];
  const draw = (query = '') => { const rows = document.querySelector('#inventory-rows'); if (!rows) return; rows.innerHTML = allItems.filter((item) => `${item.name} ${item.category}`.toLowerCase().includes(query.toLowerCase())).map((item) => `<tr><td><b>${esc(item.name)}</b><small>${esc(item.unit)}</small></td><td>${esc(item.category)}</td><td><strong>${item.onHand}</strong> ${esc(item.unit)}</td><td>${item.minLevel} ${esc(item.unit)}</td><td><span class="badge ${item.onHand <= item.minLevel ? 'danger' : 'success'}">${item.onHand <= item.minLevel ? 'Ниже минимума' : 'В норме'}</span></td></tr>`).join('') || '<tr><td colspan="5" class="empty">Ничего не найдено</td></tr>'; };
  const load = () => api('/api/inventory').then((data) => { payload = data; allItems = data.items; document.querySelector('#inventory-count').textContent = allItems.length; document.querySelector('#inventory-low').textContent = data.lowStock.length; document.querySelector('#inventory-last').textContent = data.movements[0] ? (data.movements[0].delta > 0 ? 'Приход' : 'Расход') : 'Нет'; const select = document.querySelector('#movement-item'); select.innerHTML = allItems.map((item) => `<option value="${item.id}">${esc(item.name)}</option>`).join(''); draw(document.querySelector('#inventory-search').value); }).catch(() => { document.querySelector('#inventory-rows').innerHTML = '<tr><td colspan="5" class="empty">Не удалось загрузить склад</td></tr>'; });
  document.querySelector('#inventory-search').addEventListener('input', (event) => draw(event.target.value));
  document.querySelector('#movement-form').addEventListener('submit', (event) => { event.preventDefault(); const message = document.querySelector('#movement-message'); api('/api/inventory/movements', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ itemId: document.querySelector('#movement-item').value, delta: Number(document.querySelector('#movement-delta').value), reason: document.querySelector('#movement-reason').value }) }).then(() => { message.textContent = 'Движение сохранено'; event.target.reset(); load(); }).catch((error) => { message.textContent = error.message.includes('409') ? 'Недостаточно остатка для расхода' : 'Не удалось сохранить движение'; }); });
  load();
}

function renderFinance() {
  const target = document.querySelector('#page-content'); if (!target) return;
  target.innerHTML = `<div class="page-title"><div><p class="eyebrow">КОНТРОЛЬ ДЕНЕГ</p><h1>Финансы</h1><p class="muted">Сводка оплат, выручки и заявок на скидку.</p></div><input class="date-input" type="date" value="${new Date().toISOString().slice(0, 10)}" id="finance-date"></div><div class="kpi-grid compact"><article class="kpi"><span>Выручка</span><strong id="finance-revenue">—</strong><small>С учётом VIP-минимумов</small></article><article class="kpi"><span>Закрытые заказы</span><strong id="finance-orders">—</strong><small>За выбранную дату</small></article><article class="kpi"><span>Заявки на скидку</span><strong id="finance-discounts">—</strong><small>Ожидают согласования</small></article></div><div class="content-grid"><section class="panel wide"><div class="panel-head"><h2>Оплаты по способу</h2></div><div class="payment-list" id="payment-list"></div></section><section class="panel"><div class="panel-head"><h2>Правила контроля</h2></div><div class="rule"><b>Скидка</b><span>Только через заявку с причиной и решением старшего</span></div><div class="rule"><b>VIP</b><span>Итог не ниже установленного минимума комнаты</span></div><div class="rule"><b>Аудит</b><span>Оплата, возврат и корректировка записываются в журнал</span></div></section></div>`;
  const load = () => api(`/api/finance/summary?date=${document.querySelector('#finance-date').value}`).then((summary) => { document.querySelector('#finance-revenue').textContent = money(summary.revenue); document.querySelector('#finance-orders').textContent = summary.closedOrders; document.querySelector('#finance-discounts').textContent = summary.pendingDiscounts; const rows = Object.entries(summary.byPaymentMethod); document.querySelector('#payment-list').innerHTML = rows.length ? rows.map(([method, value]) => `<div class="payment-row"><span>${esc(method)}</span><strong>${money(value)}</strong></div>`).join('') : '<div class="empty">Оплат за выбранную дату пока нет</div>'; }).catch(() => {});
  document.querySelector('#finance-date').addEventListener('change', load); load();
}

function renderReservations() {
  const target = document.querySelector('#page-content'); if (!target) return;
  target.innerHTML = `<div class="page-title"><div><p class="eyebrow">ГОСТИ И СТОЛЫ</p><h1>Бронирования</h1><p class="muted">Единый календарь броней и депозитов.</p></div><button class="button primary" id="focus-reservation">＋ Новая бронь</button></div><div class="content-grid"><section class="panel"><div class="panel-head"><h2>Новая бронь</h2></div><form id="reservation-form" class="stack-form"><label>Гость<input id="reservation-guest" required placeholder="Имя гостя"></label><label>Телефон<input id="reservation-phone" placeholder="+7 ..."></label><div class="form-row"><label>Дата<input id="reservation-date" type="date" required value="${new Date().toISOString().slice(0, 10)}"></label><label>Время<input id="reservation-time" type="time" required value="21:00"></label></div><div class="form-row"><label>Стол / комната<select id="reservation-table" required></select></label><label>Гости<input id="reservation-guests" type="number" min="1" value="2" required></label></div><label>Депозит<input id="reservation-deposit" type="number" min="0" step="100" value="0"></label><button class="button primary">Подтвердить бронь</button><p class="form-message" id="reservation-message"></p></form></section><section class="panel wide"><div class="panel-head"><h2>Ближайшие бронирования</h2><input class="table-search" id="reservation-filter" placeholder="Поиск по гостю"></div><div class="reservation-list" id="reservation-list"></div></section></div>`;
  const loadTables = () => api('/api/floor').then((data) => { const tables = data.zones.flatMap((zone) => zone.tables); document.querySelector('#reservation-table').innerHTML = tables.map((table) => `<option value="${table.id}">${esc(table.name)}${table.minimumOrderTotal ? ` — минимум ${money(table.minimumOrderTotal)}` : ''}</option>`).join(''); });
  let reservations = [];
  const draw = (query = '') => { const list = document.querySelector('#reservation-list'); const filtered = reservations.filter((item) => `${item.guestName} ${item.tableName} ${item.phone}`.toLowerCase().includes(query.toLowerCase())); list.innerHTML = filtered.length ? filtered.map((item) => `<div class="reservation-row"><div><b>${esc(item.guestName)}</b><small>${esc(item.date)} · ${esc(item.time)} · ${esc(item.tableName || item.tableId)} · ${item.guests} гостей</small></div><div><strong>${item.deposit ? `Депозит ${money(item.deposit)}` : 'Без депозита'}</strong><span class="badge ${item.status === 'confirmed' ? 'success' : 'danger'}">${item.status === 'confirmed' ? 'Подтверждена' : 'Отменена'}</span></div></div>`).join('') : '<div class="empty">Бронирований пока нет</div>'; };
  const load = () => api('/api/reservations').then((data) => { reservations = data.items; draw(document.querySelector('#reservation-filter').value); }).catch(() => {});
  document.querySelector('#reservation-filter').addEventListener('input', (event) => draw(event.target.value));
  document.querySelector('#reservation-form').addEventListener('submit', (event) => { event.preventDefault(); const message = document.querySelector('#reservation-message'); const value = { guestName: document.querySelector('#reservation-guest').value, phone: document.querySelector('#reservation-phone').value, date: document.querySelector('#reservation-date').value, time: document.querySelector('#reservation-time').value, tableId: document.querySelector('#reservation-table').value, guests: Number(document.querySelector('#reservation-guests').value), deposit: Number(document.querySelector('#reservation-deposit').value) }; api('/api/reservations', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(value) }).then(() => { message.textContent = 'Бронь подтверждена'; event.target.reset(); load(); }).catch(() => { message.textContent = 'Не удалось создать бронь'; }); });
  loadTables(); load();
}

if (page === 'dashboard') renderDashboard();
if (page === 'inventory') renderInventory();
if (page === 'finance') renderFinance();
if (page === 'reservations') renderReservations();


